<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';

use App\Repositories\{AuditRepository,SearchRepository};
use App\Services\{AuditPresenter,BusinessHoursService,ReportService};
use App\Support\{Config,Database,FrozenClock};

if(Config::get('APP_ENV')!=='testing'||!str_contains(strtolower(Config::get('DB_DATABASE')),'test'))throw new RuntimeException('Phase 4 tests require a disposable testing database.');
$db=Database::connection();$checks=0;
function p4ok(bool $condition,string $message):void{global $checks;if(!$condition){fwrite(STDERR,'FAIL: '.$message.PHP_EOL);throw new RuntimeException('FAIL: '.$message);}$checks++;}
function p4candidate(PDO $db,int $technology,string $name,string $phone,string $classification):int{$q=$db->prepare("INSERT INTO users(role,full_name,phone,password_hash) VALUES('CANDIDATE',?,?,?)");$q->execute([$name,$phone,'x']);$id=(int)$db->lastInsertId();$db->prepare('INSERT INTO candidate_profiles(user_id,technology_id,classification) VALUES(?,?,?)')->execute([$id,$technology,$classification]);return $id;}
function p4interview(PDO $db,array $v):int{$candidate=(int)$v[0];$snapshot=$db->query("SELECT u.full_name,p.classification FROM users u JOIN candidate_profiles p ON p.user_id=u.id WHERE u.id=$candidate")->fetch();$values=array_merge([$candidate,$candidate,$snapshot['full_name'],$snapshot['classification']],array_slice($v,1));$q=$db->prepare("INSERT INTO interviews(candidate_id,candidate_reference_id,candidate_name_snapshot,candidate_classification_snapshot,resource_id,support_person_id,technology_id,company_name,job_role,interview_round,hr_name,hr_phone,hr_unavailable,duration_minutes,interview_type,start_time,end_time,status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$q->execute($values);return (int)$db->lastInsertId();}

$db->exec("INSERT INTO technologies(name,active) VALUES('Phase4 Analytics',1)");$technology=(int)$db->lastInsertId();
$db->exec("INSERT INTO users(role,full_name,username,password_hash) VALUES('ADMIN','Phase Four Admin','phase.four.admin','x')");$admin=(int)$db->lastInsertId();
$genuine=p4candidate($db,$technology,'Formula =1+1 Candidate','+919300000001','Genuine');$fake=p4candidate($db,$technology,'Unicode उम्मीदवार','+919300000002','Fake');
$normal=(int)$db->query("SELECT id FROM resources WHERE resource_type='NORMAL' ORDER BY id LIMIT 1")->fetchColumn();$tool1=(int)$db->query("SELECT id FROM resources WHERE resource_type='TOOL' ORDER BY id LIMIT 1")->fetchColumn();$tool2=(int)$db->query("SELECT id FROM resources WHERE resource_type='TOOL' ORDER BY id LIMIT 1 OFFSET 1")->fetchColumn();$hari=(int)$db->query("SELECT id FROM support_people WHERE name='Hari'")->fetchColumn();$arjun=(int)$db->query("SELECT id FROM support_people WHERE name='Arjun'")->fetchColumn();
$before=p4interview($db,[$genuine,$normal,null,$technology,'Outside Before','Engineer','R1',null,null,1,30,'NORMAL','2032-04-30 18:29:00','2032-04-30 18:59:00','BOOKED','2032-04-01 00:00:00']);
$boundary=p4interview($db,[$genuine,$normal,null,$technology,'=1+1, "Quoted" Company','Engineer','Round 1','+SUM(1,2)','@someone',0,30,'NORMAL','2032-04-30 18:30:00','2032-04-30 19:00:00','BOOKED','2032-04-20 03:00:00']);
$toolHari=p4interview($db,[$genuine,$tool1,$hari,$technology,'BluJay Search Operations','Lead','Round 2','Recruiter','+919876543210',0,60,'TOOL','2032-05-01 04:30:00','2032-05-01 05:30:00','BOOKED','2032-04-21 03:00:00']);
$cancelled=p4interview($db,[$fake,$normal,null,$technology,'Cancel Company','Analyst','Final',null,null,1,45,'NORMAL','2032-05-02 05:30:00','2032-05-02 06:15:00','CANCELLED','2032-04-22 03:00:00']);
$toolArjun=p4interview($db,[$fake,$tool2,$arjun,$technology,'Unicode कंपनी','Developer','R3','HR','-1+1',0,30,'TOOL','2032-05-03 05:30:00','2032-05-03 06:00:00','BOOKED','2032-04-23 03:00:00']);
$after=p4interview($db,[$genuine,$normal,null,$technology,'Outside After','Engineer','R1',null,null,1,30,'NORMAL','2032-05-31 18:30:00','2032-05-31 19:00:00','BOOKED','2032-04-24 03:00:00']);
$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)")->execute([$fake,'booking.cancelled','interview',$cancelled,json_encode(['reason'=>'candidate']), '2032-05-02 04:00:00']);
$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)")->execute([$admin,'resource.updated','resource',$normal,json_encode(['password_hash'=>'never-show','nested'=>['csrf_token'=>'never-show','name'=>'Normal PC 1']]), '2032-05-03 04:00:00']);$secretAudit=(int)$db->lastInsertId();

$clock=new FrozenClock(new DateTimeImmutable('2032-05-15T06:00:00+00:00'));$hours=new BusinessHoursService($db,$clock);$service=new ReportService($db,$hours,$clock);
$default=$service->filters([]);p4ok($default['start']==='2032-05-01'&&$default['end']==='2032-05-15','default report range is This Month through today');
$today=$service->filters(['preset'=>'today']);p4ok($today['start_utc']==='2032-05-14 18:30:00'&&$today['end_utc']==='2032-05-15 18:30:00','Asia/Kolkata day uses correct UTC half-open boundaries');
$yesterday=$service->filters(['preset'=>'yesterday']);p4ok($yesterday['start']==='2032-05-14'&&$yesterday['end']==='2032-05-14','Yesterday preset is deterministic');
$week=$service->filters(['preset'=>'this_week']);p4ok($week['start']==='2032-05-10'&&$week['end']==='2032-05-15','This Week starts Monday');
$filter=$service->filters(['preset'=>'custom','start'=>'2032-05-01','end'=>'2032-05-03','technology_id'=>(string)$technology]);$report=$service->build($filter);$m=$report['metrics'];
p4ok((int)$m['total_interviews']===4,'range includes exact start boundary and excludes records outside');p4ok((int)$m['tool_interviews']===2&&(int)$m['normal_interviews']===2,'Tool and Normal counts correct');p4ok((int)$m['cancelled_interviews']===1,'cancelled count correct');p4ok((int)$m['unique_candidates']===2,'unique candidate count correct');p4ok((int)$m['scheduled_minutes']===120,'scheduled minutes exclude cancelled interviews');
p4ok(count($report['trend'])===3&&(int)$report['trend'][1]['cancelled']===1,'daily trend includes every day and cancellation counts');p4ok(count($report['technologies'])===1&&(int)$report['technologies'][0]['total']===4,'technology grouping correct');
$classes=array_column($report['classifications'],null,'classification');p4ok((int)$classes['Genuine']['interview_count']===2&&(int)$classes['Fake']['interview_count']===2,'classification grouping correct');
$support=array_column($report['support'],null,'name');p4ok((int)$support['Hari']['scheduled_minutes']===60&&(float)$support['Hari']['average_minutes']===60.0,'support workload and average correct');p4ok((int)$support['Hari']['active']===1,'support workload preserves directory status');p4ok((float)$support['Hari']['workload_percent']===66.7&&(float)$support['Arjun']['workload_percent']===33.3,'support workload percentages correct');
$resource=array_column($report['resources'],null,'id');p4ok((int)$resource[$normal]['booked_minutes']===30,'resource booked minutes exclude cancellation');p4ok((int)$resource[$normal]['available_minutes']===1080,'available minutes use open Saturday and Monday, excluding closed Sunday');p4ok((float)$resource[$normal]['utilization']===2.8,'resource utilization percentage correct');
$sunday=$service->build($service->filters(['preset'=>'custom','start'=>'2032-05-02','end'=>'2032-05-02','technology_id'=>(string)$technology]));$sundayResources=array_column($sunday['resources'],null,'id');p4ok((int)$sundayResources[$normal]['available_minutes']===0&&$sundayResources[$normal]['utilization']===null,'closed-day utilization handles zero denominator');
p4ok($report['sources']['candidate']===1&&$report['sources']['admin']===0&&$report['sources']['unattributed']===0,'cancellation source uses reliable audit action');
$combined=$service->build($service->filters(['preset'=>'custom','start'=>'2032-05-01','end'=>'2032-05-03','type'=>'TOOL','technology_id'=>(string)$technology,'support_person_id'=>(string)$hari,'resource_id'=>(string)$tool1,'classification'=>'Genuine']));p4ok((int)$combined['metrics']['total_interviews']===1&&(int)$combined['metrics']['scheduled_minutes']===60,'all report filters combine correctly');
$export=iterator_to_array($service->exportRows($filter));p4ok(count($export)===4&&!in_array($before,array_column($export,'id'),true)&&!in_array($after,array_column($export,'id'),true),'CSV source uses same report scope');
foreach(['=1+1','+SUM(1,2)','-1+1','@something',"  =cmd"] as $cell)p4ok(str_starts_with(ReportService::csvCell($cell),"'"),'dangerous CSV formula prefix neutralized: '.$cell);
p4ok(ReportService::csvCell('commas, quotes " and newlines'."\n".'Unicode उम्मीदवार')==='commas, quotes " and newlines'."\n".'Unicode उम्मीदवार','safe CSV content preserved for fputcsv quoting');

$search=new SearchRepository($db);p4ok(count($search->search('Formula')['candidates'])===1,'global search finds candidate name');p4ok(count($search->search('+919300000002')['candidates'])===1,'global search finds phone');p4ok(count($search->search('BluJay')['interviews'])===1,'global search finds company');p4ok(count($search->search('Search')['interviews'])===1,'global search finds a later word partial');p4ok($search->search('%_')['candidates']===[],'global search treats wildcard characters literally');p4ok(is_array($search->search("' OR 1=1 --")),'SQL-injection-like search input is handled as data');p4ok(count($search->search('Phase',2)['candidates'])<=2,'global search result limit enforced');

$auditRepo=new AuditRepository($db);$tz=$hours->timezone();$audit=$auditRepo->paginated(['date_from'=>'2032-05-01','date_to'=>'2032-05-03','actor_id'=>(string)$admin,'category'=>'resource'],$tz,1,1);p4ok($audit['total']===1&&$audit['pages']===1,'audit date, actor, category and pagination filters combine');$detail=$auditRepo->detail($secretAudit);$presented=(new AuditPresenter($tz))->one($detail,true);p4ok($presented['label']==='Resource updated'&&$presented['details']['password_hash']==='[redacted]'&&$presented['details']['nested']['csrf_token']==='[redacted]','audit detail humanizes and recursively redacts secrets');p4ok($presented['details']['nested']['name']==='Normal PC 1','audit detail retains safe structured values');
$bookingAudit=$auditRepo->paginated(['category'=>'cancellation'],$tz,1,30);p4ok((bool)array_filter($bookingAudit['rows'],fn($r)=>(int)$r['entity_id']===$cancelled),'audit booking category works');
$routes=file_get_contents(ROOT.'/routes/web.php');p4ok(str_contains($routes,"'/admin/reports'")&&str_contains($routes,"'/admin/search'")&&str_contains($routes,"'/admin/audit'")&&substr_count($routes,"'ADMIN'")>=3,'all Phase 4 routes declare admin authorization');
echo $checks." Phase 4 checks passed.\n";
